27	     * @param field     The field in which the plant resides.
28	     * @param location  The location in which the plant spawns into.
29	     */
30	    public Plant(PlantTraits traits, boolean poisonous, int foodValue, double size,
31	                 boolean randomAge, Field field, Location location) {
32	        super(randomAge, field, location);
33	        this.traits    = traits;
34	        this.size      = size;
35	        this.foodValue = foodValue;
36	        this.poisonous = poisonous;
37	        this.growthRate         = traits.growthRate;
38	        this.breedingProbability = traits.lowBreedingProbability;
39	    }
