41	    // ── Organism stat getters (satisfied here so subclasses need not override) ──
42	
43	    @Override public int    getMaxAge()        { return traits.maxAge; }
44	    @Override public int    getBreedingAge()   { return traits.breedingAge; }
45	    @Override public int    getMaxLitterSize() { return traits.maxLitterSize; }
46	
47	    @Override
48	    public double getBreedingProbability() { return breedingProbability; }
49	
