53	    @Override public double getSize()                      { return size; }
54	    @Override public double getGrowthRate()                { return growthRate; }
55	    @Override public void   setGrowthRate(double rate)     { growthRate = rate; }
56	
57	    @Override
58	    public void grow() {
59	        size = size * growthRate > traits.maxSize ? 1 : size * growthRate;
60	        if (size == 0) remove();
61	    }
62	
63	    // ── Consumable interface ───────────────────────────────────────────────────
64	
65	    @Override public int     getFoodValue()  { return foodValue; }
66	    @Override public boolean isPoisonous()   { return poisonous; }
67	
68	    @Override
69	    public void setEaten() {
70	        if (getLocation() != null) {
71	            getField().clear(getLocation());
72	            setLocationToNull();
73	            setField(null);
74	        }
75	    }
76	
77	    // ── Breeding ───────────────────────────────────────────────────────────────
78	
